        { "less eager to hurry past what could become trouble", tags = { "!back" } },
        { "more at ease with the sea than with most roads", tags = { "!back" } },
        { "at an hour that made a hunter's care worth keeping", tags = { "!back", "night" } },
        { "my stride easier once the way began to feel familiar", tags = { "back" } },
        { "less a stranger to the country than on my first coming", tags = { "back" } },
        { "hoping the same names would still mean company", tags = { "back" } },
        { "my ears doing more work than my feet admitted" },
        { "wondering what the loa found entertaining beyond the next turn" },
        { "rather keen to know the way back before I needed it", tags = { "!back" } },
        { "my caution quicker than my willingness to feel at home", tags = { "!back" } },
        { "hoping for something the tribe would enjoy hearing about", tags = { "!back" } },
        { "my eyes asking the darkness to keep fewer secrets", tags = { "!back", "night" } },
