      ["rare"] = {
        { "I brought down {foe} {at}, and hoped the loa would find somebody else's courage interesting for a while." },
        { "{foe} fell to me {at}. The Darkspear could still surprise the world, though I was grateful not to be the surprise this time." },
        { "I overcame {foe} {at}, with my heart too busy celebrating to leave much room for pride." },
        { "I killed {foe} {at}, and found the thought of a familiar shore suddenly very sweet." },
      },
      ["rest"] = {
        { "I rested {at}, leaving the loa to find their amusement without another performance from me." },
        { "I settled {at}, no more inclined to hurry than a hunter with the day's work behind him." },
        { "I paused {at}, wishing the sea were near enough to hear without another step." },
        { "I rested {at}, with enough room inside the weariness for a grin again." },
        { "I stopped {at}, ready for an evening that asked no more of a troll than sitting still." },
        { "As ready for quiet as a Darkspear after a long hunt, I rested {at}." },
        { "I paused {at}, with the tribe's familiar warmth dearer than any chance to be impressive." },
        { "I rested {at}, quite content to be the troll who knew when his feet had had enough." },
        { "Ready to let my patience serve my own body for once, I rested {at}." },
      },
      ["revived"] = {
        { "I found my body as a ghost {at}, and was grateful the loa had not decided to keep the better part of me.", tags = { "corpse" } },
        { "The spirit healer raised me {at}, with more weakness than I wanted and more life than I had feared.", tags = { "healer" } },
        { "{by} brought me back {at}; the debt would travel home with me even if the road never brought us together again.", tags = { "ally" } },
        { "My own preparation returned me to life {at}, with my pride slower to recover than the rest of me.", tags = { "self" } },
      },
      ["summit"] = {
        { "I reached level {level}, with the Darkspear's scattered shores no longer the only places that meant home to me." },
        { "At level {level}, I had more to bring my people than a tale of surviving what came after us." },
        { "I reached level {level}, and hoped Sen'jin's people would find something to smile over in the life I had made." },
      },
      ["wake"] = {
        { "I rose {at}, with the ground having made a very persuasive argument for getting up.", tags = { "!rest" } },
        { "I set out again {at}, wishing a troll's long legs came with a more forgiving back.", tags = { "!rest" } },
        { "I took up the road {at}, with enough strength restored to find the next turn interesting again.", tags = { "rest" } },
        { "With my feet rather more willing to hear the road's case, I went on {at}.", tags = { "rest" } },
      },
      ["zone"] = {
        { "I entered {zone}, hoping a Darkspear's name would travel better than the rumours that usually preceded it." },
        { "I reached {zone}, with one part of me seeking a welcome and another seeking the way back." },
        { "I came into {zone}, wondering what good the tribe might find in the road ahead." },
